#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    /* The original binary imposes the following limits:
       * Maximum total number of arguments (including the program name) is 65.
         If more are supplied, it prints "TOO_MANY".
       * At least one user‑supplied argument is required.  If none are given
         (i.e. argc == 1) it prints "EMPTY".
       * Each argument must be at most 400 characters long.  If any argument
         exceeds this length the program prints "TOO_LONG".
       * Otherwise it prints the longest common prefix of all user‑supplied
         arguments (argv[1] … argv[argc‑1]) followed by a newline.  An empty
         prefix results in just a newline.
    */

    /* Check argument count limits */
    if (argc > 65) {
        puts("TOO_MANY");
        return 0;
    }
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    /* Verify length of each argument */
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 400) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* Compute longest common prefix */
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && first[j] && s[j] && first[j] == s[j]) {
            ++j;
        }
        prefix_len = j; // shrink to the common part found so far
        if (prefix_len == 0) {
            break; // no common prefix possible any more
        }
    }

    /* Output the prefix (may be empty) */
    if (prefix_len > 0) {
        fwrite(first, 1, prefix_len, stdout);
    }
    putchar('\n');
    return 0;
}
